<script setup>
import { computed, onMounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { api } from '../api'
import { initials, percentage } from '../utils'
import ProfileForm from '../components/ProfileForm.vue'
import EmptyState from '../components/EmptyState.vue'
const profiles = ref([]), loading = ref(true), error = ref(''), search = ref(''), filter = ref('all'), creating = ref(false)
const router = useRouter()
const filtered = computed(() => profiles.value.filter(p => p.name.toLowerCase().includes(search.value.toLowerCase()) && (filter.value === 'all' || p.kind === filter.value)))
const stats = computed(() => profiles.value.reduce((a, p) => { a.lists += p.lists.length; p.lists.forEach(l => { a.total += l.total; a.correct += l.correct }); return a }, { lists: 0, total: 0, correct: 0 }))
const total = p => p.lists.reduce((a, l) => a + l.total, 0)
const correct = p => p.lists.reduce((a, l) => a + l.correct, 0)
async function load() { loading.value = true; error.value = ''; try { profiles.value = await api('/profiles') } catch (e) { error.value = e.message } finally { loading.value = false } }
onMounted(load)
function created(data) { creating.value = false; router.push(`/profiles/${data.id}`) }
</script>
<template>
  <section><div class="page-heading"><div><div class="eyebrow mb-3">У КАЖДОГО СВОЙ ПУТЬ К ЗНАНИЯМ</div><h1>Учебные профили<span class="text-sky-600">.</span></h1><p>Индивидуальный подход. Заметный прогресс. Занятия с результатом.</p></div><button class="btn primary" @click="creating = true"><Icon name="Plus" :size="17" />Новый профиль</button></div>
    <div class="profile-stats"><div class="stat-card card"><span class="stat-icon"><Icon name="Users" :size="21" /></span><div><span>Ученики и группы</span><strong>{{ profiles.length }}</strong></div></div><div class="stat-card card"><span class="stat-icon"><Icon name="Layers" :size="21" /></span><div><span>Прикреплено списков</span><strong>{{ stats.lists }}</strong></div></div><div class="stat-card card"><span class="stat-icon green"><Icon name="TrendingUp" :size="21" /></span><div><span>Общий прогресс</span><strong>{{ percentage(stats.correct, stats.total) }}<small>%</small><em>{{ stats.correct }} / {{ stats.total }}</em></strong></div></div></div>
    <div class="section-heading"><div class="tabs"><button :class="{ active: filter === 'all' }" @click="filter = 'all'">Все профили</button><button :class="{ active: filter === 'student' }" @click="filter = 'student'">Ученики</button><button :class="{ active: filter === 'group' }" @click="filter = 'group'">Группы</button></div><div class="search-field"><Icon name="Search" :size="15" /><input v-model="search" placeholder="Найти профиль…" aria-label="Поиск профилей" /></div></div>
    <div v-if="error" class="error-box mb-5">{{ error }} <button class="underline" @click="load">Повторить</button></div><div v-if="loading" class="loading"><Icon name="LoaderCircle" class="spin" />Загружаем профили…</div><div v-else-if="filtered.length" class="profiles-grid"><RouterLink v-for="(profile, i) in filtered" :key="profile.id" :to="`/profiles/${profile.id}`" class="profile-card card"><div class="profile-card-top"><div class="profile-avatar" :class="['color-' + (i % 3), { group: profile.kind === 'group' }]"><Icon v-if="profile.kind === 'group'" name="Users" :size="25" /><span v-else>{{ initials(profile.name) }}</span></div><span class="badge neutral">{{ profile.kind === 'group' ? 'Группа' : 'Ученик' }}</span></div><h3>{{ profile.name }}</h3><p class="profile-note">{{ profile.note || 'Новые знания начинаются здесь' }}</p><div class="profile-progress-label"><span>Освоено заданий</span><strong>{{ correct(profile) }} <span>/ {{ total(profile) }}</span></strong></div><div class="progress-track"><div :style="{ width: percentage(correct(profile), total(profile)) + '%' }"></div></div><div class="profile-card-bottom"><span><Icon name="FileText" :size="12" />{{ profile.lists.length }} списков</span><span>К занятиям<Icon name="ArrowRight" :size="13" /></span></div></RouterLink><button class="new-profile-card" @click="creating = true"><span><Icon name="Plus" :size="25" /></span><strong>Ещё один путь к знаниям</strong><p>Создать учебный профиль</p></button></div><EmptyState v-else icon="Users" :title="search || filter !== 'all' ? 'Профили не найдены' : 'Познакомимся с вашими учениками?'" :text="search || filter !== 'all' ? 'Измените запрос или выберите другой фильтр.' : 'Создайте профиль ученика или группы, прикрепите задания и наблюдайте, как растёт уверенность в знаниях.'" :action="search || filter !== 'all' ? '' : 'Создать первый профиль'" @action="creating = true" />
    <div class="info-banner"><Icon name="Sparkles" :size="17" /><p><strong>Прогресс складывается из маленьких шагов.</strong> В каждом профиле — свои списки, история ответов и возможность вернуться к сложному. Помогайте ученикам расти в их собственном темпе.</p></div>
  </section><ProfileForm v-if="creating" @close="creating = false" @saved="created" />
</template>
<style scoped>
