-card-bottom>span:last-child{color:#6b9aba}.new-profile-card{border:1px dashed #dbe6f1;border-radius:18px;background:#fcfdff70;min-height:250px;display:flex;flex-direction:column;align-items:center;justify-content:center;color:#9eafc1;gap:10px;padding:20px}.new-profile-card>span{width:48px;height:48px;display:flex;align-items:center;justify-content:center;background:#f5f9ff;border:1px solid #e7eef7;border-radius:15px;margin-bottom:7px}.new-profile-card strong{font-size:12px;font-weight:500}.new-profile-card p{font-size:10px}.new-profile-card:hover{background:#f4faff;border-color:#a7d3ed;color:#5c9bc5}@media(max-width:1150px){.profiles-grid{grid-template-columns:repeat(2,minmax(0,1fr))}.stat-card{padding:17px 14px;gap:10px}.stat-card em{display:none}.stat-icon{width:36px;height:36px}}@media(max-width:760px){.profile-stats{gap:8px;margin-bottom:25px}.stat-card{padding:13px 10px;gap:7px;align-items:flex-start;flex-direction:column}.stat-icon{width:29px;height:29px;border-radius:9px;margin-bottom:3px}.stat-icon svg{width:17px}.stat-card>div>span{font-size:8px}.stat-card strong{font-size:20px}.profile-card{padding:17px}.profile-card-top .badge{padding:3px 5px;font-size:7px}.profile-avatar{width:37px;height:37px;border-radius:12px;font-size:12px}.profile-card h3{font-size:12px}.profiles-grid{gap:10px}.profile-card-bottom>span:last-child{font-size:0;gap:0}.profile-card-bottom>span:last-child svg{width:15px}.new-profile-card strong{font-size:11px;text-align:center}.tabs button{font-size:10px;padding:7px 10px}}
</style>
